let lastRefillTime; // Jeton dolum hesabı için kullanılan en büyük zaman referansı

function now() {
  return Date.now();
}

class TokenBucket {
  /**
   * @param {Object} options - Konfigürasyon nesnesi.
   */
  constructor({ capacity, refillPerSecond, now = () => Date.now() }) {
    if (!Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('Capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPersecond must be a non-negative number');
    }

    this._now = now;
    this.capacity = capacity;
    this.refillRate = refillPerSecond; // jeton/saniye (ms cinsinden: refilled per ms)
    this.tokens = capacity;
    this.maxSeenTime = Date.now(); // ilk çalışma için varsayılan zaman
  }

  /**
   * Jetonleri zamana bağlı olarak doldurur.
   */
  _refill() {
    const currentNow = this._now();
    let refillDuration;

    if (this.maxSeenTime === undefined) {
      // İlk çalışma durumu: kova dolu başlar, bu yüzden refilling yapılmaz
      this.maxSeenTime = currentNow;
    } else if (currentNow > this.maxSeenTime) {
      refillDuration = currentNow - this.maxSeenTime;
      this.maxSeenTime = currentNow;
    } else {
      // Geriye doğru giden zamanlarda jeton eklenmez / çıkarılmaz
      return;
    }

    const refilledTokens = refillDuration * (this.refillRate / 1000); // ms cinsından saniye dönüşümü ile jeton miktarı
    this.tokens = Math.min(this.capacity, this.tokens + refilledTokens);
  }

  /**
   * n adet jetonu kullanmaya çalışır.
   */
  tryTake(n) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('Amount must be a positive finite number');
    }
    this._refill();
    return this.tokens >= n && (this.tokens -= n); // Jeton yeterliyse düş ve true döndür
  });

  /**
   * Mevcut jeton sayısını döner.
   */
  available() {
    this._refill();
    return this.tokens;
  }

  /**
   * n adet jetonun kullanılabilir olmasına kalan süreyi ms cinsinden döndür.
   */
  msUntil(n) {
    if (!Number.isFinite(n) || n <= 0) {
      throw new RangeError('Amount must be a positive finite number');
    }

    const currentTokens = this.available();

    if (currentTokens >= n) return 0;

    // Dolum hızı 1 saniyedeki jeton sayısıdır
    if (this.refillRate <= 0 || n > this.capacity) return Infinity;

    const needed = n - currentTokens;
    return Math.ceil((needed / this.refillRate) * 1000); // kaç sn kaldığını ms cinsinden yukarı yuvarla
  }
}

module.exports = { TokenBucket };
